interface Logger {
    void log(String message); // Abstract: Mandatory

    // Default method: Optional for implementing classes to override
    default void logWithTimestamp(String message) {
        long now = System.currentTimeMillis();
        log("[" + now + "] " + message);
    }
}

// Class 1: Uses the default implementation
class ConsoleLogger implements Logger {
    @Override
    public void log(String message) {
        System.out.println("[CONSOLE] " + message);
    }
}

// Class 2: Customizes and overrides the default implementation
class FormattedLogger implements Logger {
    @Override
    public void log(String message) {
        System.out.println(message);
    }

    @Override
    public void logWithTimestamp(String message) {
        System.out.println("[CUSTOM-TS 2026-10-03] >>> " + message);
    }
}

public class DefaultDemo {
    public static void main(String[] args) {
        Logger c = new ConsoleLogger();
        c.logWithTimestamp("Server booted");

        Logger f = new FormattedLogger();
        f.logWithTimestamp("Cache initialized");
    }
}

