interface AlarmAlert {
    default void sound() {
        System.out.println("BEEP! BEEP! BEEP!");
    }
}

interface SirenAlert {
    default void sound() {
        System.out.println("WEE-WOO-WEE-WOO!");
    }
}

// Class implements both: Conflict must be resolved explicitly!
class EmergencySystem implements AlarmAlert, SirenAlert {
    @Override
    public void sound() {
        System.out.println("=== Emergency Activated ===");
        // Disambiguate using InterfaceName.super.method()
        AlarmAlert.super.sound();
        SirenAlert.super.sound();
    }
}

public class ConflictDemo {
    public static void main(String[] args) {
        EmergencySystem sys = new EmergencySystem();
        sys.sound();
    }
}

