import java.util.Map;
import java.util.HashMap;

interface KeyValStore {
    void put(String k, String v);
    String get(String k);
    default String getOrDefault(String k, String defaultVal) {
        String val = get(k);
        return (val != null) ? val : defaultVal;
    }
    default boolean containsKey(String k) {
        return get(k) != null;
    }
}

class SimpleMapStore implements KeyValStore {
    private Map<String, String> map = new HashMap<>();
    @Override
    public void put(String k, String v) {
        map.put(k, v);
    }
    @Override
    public String get(String k) {
        return map.get(k);
    }
}

public class StoreApp {
    public static void main(String[] args) {
        KeyValStore store = new SimpleMapStore();
        store.put("env", "production");
        System.out.println("Env: " + store.getOrDefault("env", "dev"));
        System.out.println("Timeout: " + store.getOrDefault("timeout", "30s"));
        System.out.println("Contains env: " + store.containsKey("env"));
    }
}
